"use client"
import React from 'react'

export default function Notifications({items}:{items:{id:string,title:string,body:string,time:string}[]}){
  return (
    <div style={{background:'#fff',padding:16,borderRadius:10,boxShadow:'0 1px 2px rgba(0,0,0,0.03)',width:320}}>
      <h4 style={{margin:'0 0 12px 0'}}>Notifications</h4>
      <ul style={{listStyle:'none',padding:0,margin:0}}>
        {items.map(n=> (
          <li key={n.id} style={{padding:'8px 0',borderTop:'1px solid #f3f4f6'}}>
            <div style={{fontWeight:600}}>{n.title}</div>
            <div style={{fontSize:13,color:'#6b7280'}}>{n.body}</div>
            <div style={{fontSize:12,color:'#9ca3af',marginTop:6}}>{n.time}</div>
          </li>
        ))}
      </ul>
    </div>
  )
}
